// Uses the overview and graphs generated by tests/render_pages.py.
const fs = require('fs');
const path = require('path');
const assert = require('node:assert/strict');
const { JSDOM } = require('jsdom');
const script = name => fs.readFileSync(path.join(__dirname, '..', 'static', name), 'utf8');
function openPage(name) {
    return new JSDOM(fs.readFileSync('/tmp/fish-' + name + '.html', 'utf8'), {
        url: 'http://localhost/', runScripts: 'outside-only', pretendToBeVisual: true
    });
}
function checkScene() {
    const dom = openPage('index');
    const w = dom.window, doc = w.document, reef = doc.querySelector('.reef');
    let timestamp = Date.UTC(2026, 10, 7, 21), refresh, onMotionChange, played = 0;
    w.Date = class extends Date { constructor() { super(timestamp); } };
    w.setInterval = callback => { refresh = callback; };
    const media = {matches: false, addEventListener: (_, callback) => { onMotionChange = callback; }};
    w.matchMedia = () => media;
    reef.querySelector('.reef-ripple').animate = () => { played++; return {cancel() {}}; };
    w.eval(script('aquarium.js'));
    for (const [utc, expected] of [[21,'dawn'], [23,'day'], [9,'dusk'], [11,'night']]) {
        timestamp = Date.UTC(2026, 10, 7, utc);
        refresh();
        assert.equal(reef.dataset.light, expected);
    }
    const light = doc.querySelector('#reef-light');
    light.value = 'day';
    light.dispatchEvent(new w.Event('change'));
    assert.equal(reef.dataset.light, 'day');
    assert.equal(w.localStorage.getItem('aquapi-scene-light'), 'day');
    doc.querySelector('#reef-ripple').click();
    assert.equal(played, 1);
    doc.querySelector('#reef-motion').click();
    assert.equal(reef.dataset.paused, 'true');
    assert(doc.querySelector('#reef-ripple').disabled);
    doc.querySelector('#reef-motion').click();
    media.matches = true; onMotionChange();
    assert(doc.querySelector('#reef-motion').disabled);
    w.HTMLCanvasElement.prototype.getContext = () => new Proxy({}, {get: () => () => {}});
    w.temperatureText = n => n.toFixed(1) + ' °C';
    w.clarityLevels = ['Bright','Light haze','Murky'];
    const detail = {data:{ph:'7.02',float_stat:'Water level is Normal',turbidity:'Murky',clarityCategory:'Cloudy',
                          alerts:[{sensor:'Turbidity',type:'limit',severity:'warning'}]},
                    values:{temp:26.9,ph:7.02,water:2,clarity:2}};
    w.dispatchEvent(new w.CustomEvent('aquapi-readings', {detail}));
    assert.equal(doc.querySelectorAll('details.probe').length,4);
    assert.equal(doc.querySelector('#temp-val').textContent,'26.9 °C');
    const probe = doc.querySelector('.probe-clarity');
    probe.querySelector('summary').click();
    assert(probe.open);
    assert.deepEqual(Array.from(probe.querySelectorAll('.probe-ends span'), el => el.textContent), ['Bright','Murky']);
    const school = doc.querySelector('.reef-school');
    const add = doc.querySelector('#fish-add'), remove = doc.querySelector('#fish-remove');
    const picker = doc.querySelector('#fish-picker');
    picker.showModal = () => picker.setAttribute('open','');
    picker.close = () => picker.removeAttribute('open');
    const quantity = doc.querySelector('#fish-quantity');
    function choose(id, count = 1) {
        add.click();
        assert(picker.open);
        assert.equal(quantity.value,'1');
        assert.equal(quantity.options.length,24 - school.childElementCount);
        quantity.value = String(count);
        picker.querySelector('[data-species="' + id + '"]').click();
        assert(!picker.open);
    }
    assert.equal(school.childElementCount,10);
    assert.equal(doc.querySelector('#fish-count').textContent, '10');
    add.click();
    doc.querySelector('#fish-picker-close').click();
    assert.equal(school.childElementCount,10);
    choose('tiger-barb',5);
    assert.equal(school.childElementCount,15);
    assert.equal(school.querySelectorAll('[data-species="tiger-barb"]').length,5);
    assert.equal(school.lastElementChild.dataset.species,'tiger-barb');
    choose('glo-tetra');
    assert.equal(JSON.parse(w.localStorage.getItem('aquapi-scene-fish-roster')).at(-1),'glo-tetra');
    remove.click();
    assert.equal(school.lastElementChild.dataset.species,'tiger-barb');
    for (const color of ['orange','red','green','blue']) {
        const species = 'glo-tetra-' + color;
        choose(species);
        assert.equal(school.lastElementChild.dataset.species, species);
        assert.equal(JSON.parse(w.localStorage.getItem('aquapi-scene-fish-roster')).at(-1), species);
    }
    choose('blue-tang',5);
    assert.equal(school.childElementCount,24);
    assert(add.disabled);
    for (let i = 0; i < 30; i++) remove.click();
    assert.equal(school.childElementCount,0);
    assert(remove.disabled);
    choose('glo-tetra');
    assert(school.querySelector('img').src.endsWith('/glo-tetra.webp'));
    assert.equal(school.querySelector('img').alt,'');
    assert.equal(doc.querySelector('#fish-count').textContent,'1');
    const panel = doc.querySelector('.reef-instruments');
    panel.querySelector('summary').click();
    assert(!panel.open);
    panel.querySelector('summary').click();
    assert(panel.open);
    assert.equal(probe.dataset.state,'warning');
    assert.equal(probe.querySelector('strong').textContent,'Murky');
    assert.equal(probe.querySelector('a').getAttribute('href'),'/graphs#turbidityChart');
    detail.data.connection = {stale:true};
    w.dispatchEvent(new w.CustomEvent('aquapi-readings',{detail}));
    assert.equal(probe.querySelector('strong').textContent,'—');
    assert.equal(probe.querySelector('.probe-state').textContent,'Offline');
    dom.window.close();
}
async function checkGraphs() {
    const dom = openPage('graphs'), w = dom.window, doc = w.document;
    w.setInterval = () => 1;
    w.HTMLCanvasElement.prototype.getContext = () => new Proxy({}, {get: () => () => {}});
    const sample = {turbidity: 'Custom reading', clarityLabels: ['Bright','Custom reading'], clarityCategory: 'Cloudy', turbidityNTU: 0,
                    turbidityNTUState: 'calibrated', connection: {stale:false}, alerts:[]};
    w.fetch = async () => ({ok: true, json: async () => sample});
    w.eval(script('script.js'));
    await new Promise(resolve => setTimeout(resolve, 30));
    const status = doc.querySelector('#clarity-plot-status');
    assert.equal(doc.querySelector('#clarity-plot'), null);
    assert.equal(status.textContent, 'Custom reading');
    sample.clarityLabels = ['Only label'];
    sample.turbidity = 'Only label';
    await w.updateDashboard();
    assert.equal(status.textContent, 'Only label');
    sample.connection.stale = true; await w.updateDashboard();
    assert.equal(status.textContent, 'Waiting for clarity');
    dom.window.close();
}
checkScene();
checkGraphs().then(() => console.log('Aquarium lighting, motion, and graph checks passed.'))
    .catch(error => { console.error(error); process.exitCode = 1; });
